const CFG=window.CFL_CONFIG||{};

const PLAIN={M01:['Thinks profit is cash','Treats Net Income as if it were the cash the business made.'],M02:['Uses the balance instead of the change','Enters the ending balance where the statement needs ending minus beginning.'],M03:['Subtracts the wrong way round','Computes beginning minus ending, so increases look like decreases.'],M04:['A/R up = cash in','When customers owe more, assumes more cash came in. It is the opposite: that revenue is still uncollected.'],M05:['A/R down = subtract','When A/R falls, subtracts. A fall means old receivables were collected, so cash is ahead of this year\'s revenue: add.'],M06:['A/P up = cash paid','When A/P rises, thinks cash went out. A rise means costs were recorded but not yet paid: add it back.'],M07:['A/P down = add','When A/P falls, adds. A fall means cash left to pay old bills: subtract.'],M08:['Mixes up A/R and Unearned Revenue','Who owes whom is reversed: A/R means customers owe us; Unearned means we owe the customer work.'],M09:['Mixes up payables and prepaids','Confuses "expense first, cash later" (A/P, accrued) with "cash first, expense later" (prepaids).'],M10:['Treats deposits as earned','Counts customer deposits as revenue before the work is done.'],M11:['Treats a prepayment as this year\'s expense','Puts the whole prepaid amount into expense instead of only the part used.'],M12:['Treats buying inventory as an expense','Expenses inventory when bought instead of when sold (COGS).'],M13:['Misses the Inventory/A/P offset','Does not see that a credit purchase gives −Inventory and +A/P that cancel to zero cash.'],M14:['Applies the shortcut to the wrong account','Uses the current-asset/liability rule on debt, equipment, or Cash itself.'],M15:['Adjusts Cash itself','Adds a "change in Cash" line inside the statement that is supposed to explain it.'],M16:['Depreciation as a cash payment','Treats depreciation expense as money that left this year.'],M17:['Adds a gain','Adds the gain in Operating; it must be subtracted (the cash is in Investing).'],M18:['Subtracts a loss','Subtracts the loss in Operating; it must be added back.'],M19:['Gain used as the sale proceeds','Puts the gain/loss amount in Investing instead of the cash received.'],M20:['Book value used as proceeds','Reports the asset\'s book value instead of what the buyer paid.'],M21:['Balance change used as cash','Uses the change in the Equipment balance as the cash paid, without the additional information.'],M22:['Borrowing counted as revenue','Treats loan proceeds like income.'],M23:['Loan repayment as an expense','Puts principal repayment in Operating.'],M24:['Stock sale counted as revenue','Treats owner investment like income.'],M25:['Dividends as an expense','Puts dividends in Operating.'],M26:['Noncash deal counted as cash','Puts an equipment-for-note trade into Investing/Financing even though no cash moved.'],M27:['Picks the wrong statement section','Puts the line in Investing or Financing (or disclosure) when it belongs in Operating, or vice versa. Early on this is often clicking without reading the section menu.'],M28:['Confuses change with balance','Answers "where cash ended" when asked "how much it moved."'],M29:['Counts a sale twice','Leaves the sale in Operating and also in Investing.'],M30:['Skips a supplemental fact','Leaves out an item that only appears in the notes.'],M31:['Right direction, wrong number','Knows whether it rose or fell but the change amount is off (before today, a typed minus sign also landed here).'],M32:['Account meaning reversed','Says "we owe more" when it is "they owe us more," or similar.'],M33:['Other reasoning slip','Did not match a named pattern.'],M34:['Looked in the wrong place','Went to the wrong statement or section to find the account (a source-location slip, not a cash-flow classification error).']};
const plainTitle=c=>(PLAIN[c]||[MISCONCEPTIONS[c]||c])[0], plainWhat=c=>(PLAIN[c]||[])[1]||'';
const TEACH_PROMPTS={M01:'Beacon earned $1,000 but collected $700. Which number is profit, and which is cash? Why are they different?',M02:'Is $500 how much A/R changed, or how much it is now? Which one does the statement need?',M03:'Which balance is the ending one? Subtract beginning from ending out loud.',M04:'If customers owe us more than before, did we collect more cash or less?',M05:'A/R went down. Where did that money come from, and was that revenue counted this year or earlier?',M06:'A/P went up. Did we pay more or less than the costs we recorded?',M07:'A/P went down. Did cash leave this year for costs we had already counted?',M08:'Who owes whom? A/R: customers owe us. Unearned revenue: we owe the customer work.',M09:'Which came first here, the cash or the expense?',M10:'Customers paid in advance. Has Beacon earned that money yet? What does Beacon still owe them?',M11:'We paid for a year of insurance. How much of it has reached the Income Statement so far?',M12:'When does the cost of inventory hit the Income Statement: when we buy it or when we sell it?',M13:'Inventory +100 and A/P +100 on a credit purchase: how much cash moved? What should the two adjustments add up to?',M14:'Is this account part of day-to-day operating? Where would its cash actually show up?',M15:'Cash is the thing we are explaining. Can the answer be part of the question?',M16:'When Beacon records depreciation, who gets paid? When was the cash for that equipment actually spent?',M17:'The gain made Net Income bigger. Did it bring operating cash in? Where did the real cash from the sale go?',M18:'The loss made Net Income smaller. Did any operating cash leave because of it?',M19:'How much cash did the buyer hand over? Is that the gain, the book value, or something else?',M20:'Book value is what our records said. What did the buyer actually pay?',M21:'Equipment went up $4,000. Can we be sure that is what we paid? What else moves that balance?',M22:'The bank gave us $5,000. Did we earn it?',M23:'Paying back the loan: is that a cost of running the business, or returning money to a lender?',M24:'Owners put in cash for stock. Is that revenue?',M25:'Dividends: an expense of operating, or cash returned to owners?',M26:'Equipment was acquired with a note. How much cash moved? Then can it be a cash flow?',M27:'Who is on the other side of this cash: a customer or employee, a long-term asset, or a lender or owner?',M28:'Is $13,000 where cash ended, or how much it moved?',M29:'You put the sale in Investing. Did you also leave part of it in Operating?',M30:'Which supplemental fact have you not used yet?',M34:'Where on the statements does this account live? Current assets, current liabilities, long-term, or the notes?'};let rows=[],connection=null,selectedConcept='accounts_receivable';const loaded=load();if(loaded.state.identity)rows=[summarize(loaded.state,CFG)];
const status=document.querySelector('#cloud-status'),root=document.querySelector('#dashboard'),dialog=document.querySelector('#detail');
const COLUMNS=['accounts_receivable','accounts_payable','accrued_liabilities','unearned_revenue','prepaid_expenses','inventory','depreciation','gain_on_sale','loss_on_sale','ppe_purchase','borrowing','full_statement'];
const heat=m=>{if(!m||m.state==='Not started')return '<span class="heat not-started">—</span>';const pct=m.score==null?'':Math.round(m.score*100)+'%';const n=m.count||0;return `<span class="heat ${m.state.toLowerCase()}" title="${esc(STATE_HELP[m.state]||'')}">${esc(m.state)}</span><div class="small muted">${pct?pct+' on '+n+' independent':n+' guided only'}</div>`;};
const STATE_HELP={'Not started':'Has not reached this concept yet.',Learning:'Has seen the lesson; only guided (hand-held) answers so far, which do not count toward a score.',Practicing:'Has answered on their own, but fewer than 3 recent independent problems were right in a row (or only one direction seen).',Secure:'Recent independent problems mostly right (about 75%+), both increase and decrease seen. Ready for mixed practice.',Mastered:'85%+ on the last several independent problems including mixed practice, both directions right, no worked answer used recently.'};
function filtered(){return rows.filter(r=>!document.querySelector('#block').value||r.block===document.querySelector('#block').value).sort((a,b)=>{switch(document.querySelector('#sort').value){case 'help':return Number(b.needsHelp)-Number(a.needsHelp);case 'progress':return b.introduced-a.introduced;case 'mastery':return a.secure-b.secure;case 'module':return a.currentModule.localeCompare(b.currentModule);case 'last':return b.lastActive-a.lastActive;case 'eta':{const x=progressFor(a).eta??1e9,y=progressFor(b).eta??1e9;return y-x;}default:return a.name.localeCompare(b.name);}});}


const MODS=curriculum(CFG);
function answerKey(q){const c=q.correct;if(c==null)return '—';if(typeof c==='object'&&!Array.isArray(c)){if(c.section!=null)return `${c.section} · ${money(c.amount)}`;if(c.direction)return `${c.direction} · ${money(c.amount)}`;return JSON.stringify(c);}return Array.isArray(c)?c.join(', '):String(typeof c==='number'?money(c):c);}
function problemHTML(p,{showSource=true}={}){if(p.type==='observe'){let vis='';try{vis=p.visual?.learning?learningVisual(p.visual.learning,CFG):'';}catch(e){vis='';}return `<div class="key-item"><div class="eyebrow">Story screen</div><h3>${esc(p.title)}</h3>${(p.body||[]).map(t=>`<p>${esc(t)}</p>`).join('')}${vis?`<div class="key-src">${vis}</div>`:''}</div>`;}
 const src=showSource&&p.source?`<div class="statement key-src">${p.source.bs?.length?sourceHTML(p.source,'bs',null,CFG):''}${p.source.is?.length?sourceHTML(p.source,'is',null,CFG):''}${p.source.supplemental?.length?`<p class="small muted">${p.source.supplemental.map(esc).join(' ')}</p>`:''}</div>`:'';
 return `<div class="key-item"><div class="eyebrow">${esc(conceptName(p.concept,CFG))} · level ${p.scaffoldLevel??'—'} · ${esc(p.id)}</div><p class="small muted">${esc(p.intro||'')}</p>${src}<ol class="key-steps">${(p.prompts||[]).map(q=>`<li><b>${esc(q.text)}</b>${q.choices?`<div class="small">Choices: ${q.choices.map(c=>esc(c.label)).join(' · ')}</div>`:''}<div class="small"><span class="key-ans">Answer: ${esc(answerKey(q))}</span></div></li>`).join('')}</ol>${p.hints?.length?`<details><summary class="small">Hints (${p.hints.length})</summary><ol class="small">${p.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details>`:''}${p.explanation?`<p class="small"><b>Full reasoning:</b> ${esc(p.explanation)}</p>`:''}</div>`;}
function openModuleKey(id){const m=MODS.find(x=>x.id===id);const items=lesson(id,CFG);document.querySelector('#detail-title').textContent=`${m.title} — ${items.length} screens`;let plan='';try{plan=coachingHTML(m.id==='gain_on_sale'?'gain_on_sale':m.id,null,CFG);}catch(e){plan='';}document.querySelector('#detail-body').innerHTML=`<p class="small muted">${esc(m.what||'')} ${m.why?'· '+esc(m.why):''}</p>${plan?`<details class="plan"><summary><b>Teacher conversation plan for this module</b> · probes, listen-for, reteach, fresh check</summary>${plan}</details>`:''}`+items.map((p,i)=>`<div class="eyebrow" style="margin-top:14px">Screen ${i+1} of ${items.length}</div>`+problemHTML(p)).join('');dialog.showModal();}
function openAttempt(a){try{let p=null;try{p=recordedProblem(a);}catch(e){p=null;}let note='';if(!p){p=generate(a.concept,a.seed,a.scaffoldLevel??2,a.direction,CFG);note='<p class="small muted">Rebuilt from this student\'s seed (older attempt without a saved snapshot); the numbers match what they saw for generated problems.</p>';}document.querySelector('#detail-title').textContent=`What this student saw · ${conceptName(a.concept,CFG)}`;document.querySelector('#detail-body').innerHTML=note+`<p class="small">Answered: <b>${esc(readable(a.response))}</b> · Correct: <b>${esc(readable(a.correctResponse))}</b>${a.misconceptionCode?` · ${esc(plainTitle(a.misconceptionCode))}`:''}</p>`+problemHTML(p);dialog.showModal();}catch(e){document.querySelector('#detail-title').textContent='Problem';document.querySelector('#detail-body').innerHTML=`<p>This one came from a fixed lesson screen rather than a generated problem. Open the module in the curriculum browser to see it.</p>`;dialog.showModal();}}
const CHANGED_TODAY={three_sections:'two-methods screen',accounts_receivable:'plain opener + ladder',accounts_payable:'plain opener + ladder',accrued_liabilities:'plain opener + ladder',unearned_revenue:'plain opener + ladder',prepaid_expenses:'plain opener + ladder',inventory:'plain opener + ladder',depreciation:'plain opener + ladder',gain_on_sale:'rebuilt: cash first, two jobs, book value last',ppe_purchase:'rebuilt: method change, clues, partial-cash',borrowing:'method change, interest caveat',noncash_investing_financing:'plain opener'};
function curriculumHTML(){return `<section class="heat-section"><h2>Browse the curriculum</h2><p class="small muted"><b>View as student</b> opens the real lesson in a preview tab (nothing is saved to the class record). <b>Answer key</b> lists every screen, question, answer and hint.</p><div class="mod-grid">${MODS.map((m,i)=>`<div class="mod-card"><div class="mod-head"><span class="num">${String(i+1).padStart(2,'0')}</span><span><b>${esc(m.title)}</b><small>${esc(m.group)} · ${lesson(m.id,CFG).length} screens${CHANGED_TODAY[m.id]?` · <span class="changed">changed today: ${esc(CHANGED_TODAY[m.id])}</span>`:''}</small></span></div><div class="mod-actions"><a class="btn small" target="_blank" rel="noopener" href="./index.html?preview=1&module=${encodeURIComponent(m.id)}">View as student ↗</a><button class="small" data-module-key="${m.id}">Answer key</button></div></div>`).join('')}</div></section>`;}

// ---- Progress + ETA: modules/prompts remaining, pace from timestamps, difficulty-weighted estimate ----
const PP=Object.fromEntries(MODS.map(m=>[m.id,lesson(m.id,CFG).reduce((n,it)=>n+(it.prompts?it.prompts.length:0),0)]));
const TOTAL_PROMPTS=Object.values(PP).reduce((a,b)=>a+b,0);
const WEIGHT=(g)=>/Foundation/.test(g)?0.8:/Timing/.test(g)?1:/Noncash/.test(g)?1.1:1.25;
function progressFor(r){const idx=Math.max(0,MODS.findIndex(m=>m.id===r.currentModule));const completed=r.completedModules||[];const doneMods=MODS.filter(m=>completed.includes(m.id));const donePrompts=doneMods.reduce((n,m)=>n+PP[m.id],0);
 const rem=MODS.filter(m=>!completed.includes(m.id));let remWeighted=0,remPrompts=0;for(const m of rem){const share=m.id===r.currentModule?0.5:1;remPrompts+=PP[m.id]*share;remWeighted+=PP[m.id]*share*WEIGHT(m.group);}
 const at=(r.recentAttempts||[]);let pace=null;if(at.length>=6){const span=(at.at(-1).timestamp-at[0].timestamp)/60000;if(span>=3)pace=at.length/span;}
 const eta=pace?Math.round(remWeighted/pace):null;return {modsDone:doneMods.length,modsLeft:rem.length,promptsDone:donePrompts,promptsLeft:Math.round(remPrompts),pace,eta};}
function etaText(p){if(p.modsLeft===0)return 'Learn complete';if(!p.pace)return `${p.modsLeft} modules · ~${p.promptsLeft} questions left`;const h=Math.floor(p.eta/60),m=p.eta%60;return `${h?h+' h ':''}${m} min (${p.modsLeft} modules, ~${p.promptsLeft} q)`;}

// ---- Coaching scripts: the trick behind each concept, in words you can say ----
const TRICK={
 cash_change:{click:'A road trip odometer. You know you started at 10,000 and ended at 13,000. Nobody cares about 13,000 by itself; the story is the 3,000 miles. Where did they go?',why:'The balance sheet already tells you where cash ended. The only thing left to explain is the movement, and three stories (operating, investing, financing) must add up to exactly that movement or something is missing.',ask:['What was in the bank at the start? At the end?','So how much did it move, and which way?','What could possibly make it move: customers and bills, buying/selling big equipment, or borrowing and owners? Those are the only three doors.'],trap:'Students answer with the ending balance. If they say 13,000, ask "did cash go UP by 13,000?"'},
 three_sections:{click:'Three doors cash can walk through. Door 1 is the shop floor: customers, employees, suppliers, the day-to-day. Door 2 is the garage: buying or selling big long-lasting stuff. Door 3 is the bank and the owners: money lent, repaid, invested, or paid out.',why:'The reader wants to know whether the business itself makes cash (door 1) or is just borrowing it (door 3) or selling off equipment (door 2). Mixing the doors hides that.',ask:['Who is on the other side of this cash: a customer, a piece of equipment, or a lender/owner?','Is this part of the normal daily business, or a one-off big purchase, or financing?','Is it the business doing its business (selling, buying what it sells, paying workers and bills)? If yes, Operating, even if it is rare. Buying equipment is Investing even if it happens often.'],trap:'Stock sale or a loan "feels like income." Ask: did we EARN it, or do we owe it / did an owner hand it over?'},
 indirect_bridge:{click:'A waiter\'s tips. He earned $100 in tips tonight, but $30 of it is on credit-card slips he gets paid for next week. His "income" tonight is $100; the cash in his pocket is $70. Both are true. The $30 is the gap.',why:'Net Income counts work when it is done; cash counts money when it moves. They are two honest answers to two different questions, so to get from one to the other you add or remove exactly the places where timing differed.',ask:['How much did Beacon earn this month? How much actually arrived?','Where is the rest? (Still owed by customers.)','So to get from profit to cash, do we add that or take it away?'],trap:'"Profit means money in the bank." Point at the $300 still in the customer\'s pocket.'},
 accounts_receivable:{click:'An IOU jar. Every time Beacon does work and gets an IOU instead of cash, the jar gets fuller. If the jar is fuller at year-end than at the start, more work got IOUs this year than got paid: some of this year\'s revenue is sitting in the jar as paper, not cash. If the jar is emptier, customers paid off old IOUs: cash came in for revenue counted last year.',why:'Revenue was counted at work time. The IOU jar is the running tally of counted-but-uncollected. Its change is exactly how far cash lagged (jar up) or caught up (jar down).',ask:['Is the IOU jar fuller or emptier than it was?','Fuller means customers owe us more. Did we collect more cash than we earned this year, or less?','If we collected less than we earned, is Net Income bigger than cash or smaller? So what do we do to Net Income?'],trap:'"A/R went up, so we have more money." An IOU is not money. Ask them to hold an IOU and try to buy lunch with it.'},
 accounts_payable:{click:'The bar tab (an example with something consumed right away). You ran up $500 of drinks but only paid $300 so far; $200 is still on the tab. Your "expenses" are $500; the cash that left your wallet is $300. For inventory bought on account, the same idea applies to purchases: the A/P change tells you how much of this year’s purchases and costs were not yet paid in cash.',why:'A bigger payable at year-end means cash paid to suppliers was less than the purchases and costs recorded, so add the increase. A smaller payable means cash paid was more than the purchases and costs recorded, so subtract the decrease. With inventory, read the Inventory and A/P adjustments together: a credit purchase of unsold goods raises both, and the two adjustments cancel to zero cash.',ask:['Is the tab bigger or smaller than it was?','Bigger: did more cash leave than the costs we recorded, or less?','If less cash left than we expensed, is Net Income too low compared with cash? So add or subtract?'],trap:'"A/P went up, so we paid more." Owing MORE means paying LESS. Say it that way.'},
 accrued_liabilities:{click:'Payday on the 5th. Employees worked the last week of December; they get paid January 5. The work (expense) belongs to December; the cash belongs to January. Accrued wages is the sticky note on the fridge saying "we owe them a week."',why:'Same engine as A/P, just no invoice. Sticky note bigger: expense counted, cash not gone, add back. Sticky note smaller: we paid off old notes, subtract.',ask:['Did the employees do the work this year?','Did the cash leave this year?','So Net Income took the hit but cash did not. Which way do we fix that?'],trap:'Treating it like a different rule from A/P. It is the same rule: cost first, cash later.'},
 unearned_revenue:{click:'A gift card. Someone hands Beacon $50 for a gift card in December. Beacon has the cash, but it has not EARNED anything yet; it owes a $50 tune-up. When the card is redeemed in March, Beacon earns the revenue, but no new cash arrives.',why:'Cash came first, revenue later: the mirror image of A/R. More unredeemed cards at year-end means cash came in beyond what was earned: add. Fewer means cards got redeemed: revenue counted with no new cash, subtract.',ask:['Who has the money right now? (Beacon.) Has Beacon done the work? (No.)','So is the revenue counted yet? Is the cash in?','Cash is ahead of revenue. Is Net Income bigger or smaller than cash? So add or subtract?'],trap:'Hearing "revenue" and assuming it was earned. It is UNearned: a debt of work owed.'},
 prepaid_expenses:{click:'Paying for a year of Netflix up front. $120 leaves your account in January; by June you have "used" $60 of it. Your expense so far is $60; the cash gone is $120. The other $60 is prepaid: paid, not yet used.',why:'Cash first, expense later: the mirror of A/P. Prepaid bigger: cash left that Net Income has not counted yet, subtract. Prepaid smaller: expense counted for cash that left earlier, add.',ask:['When did the money leave?','How much of what we paid for have we actually used up?','So did more cash leave than expense was counted? Net Income is too high compared with cash, so?'],trap:'Expensing the whole payment. Ask: have you watched all twelve months of Netflix yet?'},
 inventory:{click:'Stocking a lemonade stand. You buy $100 of lemons. No expense yet: nothing is sold. The cost only becomes an expense (COGS) when the cup sells. More lemons in the fridge at year-end means cash is sitting in unsold lemons: subtract. Fewer means you sold off old lemons bought earlier: the expense hit now, the cash left earlier, add. If you bought the lemons on credit, the A/P increase cancels it, because no cash actually moved.',why:'Inventory is cash converted into goods, waiting. The statement needs to show that cash as spent when it was spent, not when the goods sell.',ask:['When we bought the goods, did it hit Net Income? (No: not until sold.)','Did cash leave? (Yes, unless bought on credit.)','So cash is out but profit has not felt it: subtract. Now, if we bought on credit, what does A/P do?'],trap:'"Inventory went up, so expenses went up." Buying is not expensing. Selling is.'},
 depreciation:{click:'A $12,000 car that you expense $1,000 a year for twelve years. In year 5 you "spend" $1,000 of depreciation, but nobody gets a check. The check was written in year 1. Depreciation is accounting spreading the old purchase over time.',why:'The cash left when the asset was bought (Investing, that year). Every later year, Net Income is lowered by an expense that moved no cash, so to get back to cash you add it back. It is not "free cash"; it is undoing a paper expense.',ask:['When we recorded depreciation, who got paid? (Nobody.)','Did Net Income go down anyway? (Yes.)','So Net Income is too low compared with cash. What do we do?'],trap:'"Add back depreciation" sounds like depreciation generates cash. It does not; it just never took any.'},
 amortization:{click:'Depreciation for things you cannot kick: a patent, software, a trademark. Same spreading of an old cost over years, same zero cash.',why:'Noncash expense lowered Net Income; add it back to get to cash.',ask:['Who got paid this year for amortization? Nobody.','Did Net Income drop? Yes.','So?'],trap:'Treating it as a new rule. It is depreciation with a different name.'},
 gain_on_sale:{click:'Selling your old phone. It cost $800; it is "worth" $200 on your books (book value) after two years. A buyer pays you $300. The $300 is the cash. The $100 "gain" is just the difference between what the books said and what the buyer paid. You never received a $100 bill called "gain"; you received $300.',why:'The $100 gain is inside Net Income. The $300 cash is an Investing inflow. If you leave the gain in Operating AND put $300 in Investing, you have counted $100 twice. So: subtract the gain in Operating, report the proceeds in Investing.',ask:['How much cash did the buyer hand over? (Point to proceeds.)','Where does the money from selling a long-term asset go on the statement? (Investing.)','The gain is already in Net Income. If we also count the full $300 in Investing, what gets double counted? So what do we remove from Operating?'],trap:'Putting the gain (or book value) in Investing. Only one of the five numbers is cash; make them point to it.'},
 loss_on_sale:{click:'Same phone, but the buyer pays $150 against a $200 book value. Cash in: $150, Investing. The $50 "loss" lowered Net Income, but no operating cash left because of it; it is just the books admitting the phone was worth less than they said.',why:'The loss sits in Net Income as if cash left. It did not. Add it back in Operating; put the $150 cash in Investing.',ask:['How much cash came in? Where does it go?','Did any operating cash leave because of the loss? (No.)','So Net Income is too low. Add it back.'],trap:'Subtracting the loss "because it is a loss." A loss on sale is a paper hit, not a cash outflow.'},
 ppe_purchase:{click:'Buying a $20,000 truck is Investing, for the cash actually paid. Equipment at cost goes up with purchases and down by the original cost of equipment sold; depreciation goes into Accumulated depreciation, not Equipment. So a $4,000 change in Equipment does not mean a $4,000 purchase if something was also sold. Use the note that says what was paid.',why:'The statement reports real cash flows, and the balance change can net a purchase and a sale together. Use the stated cash purchase when the problem gives it; otherwise reconcile the balance change with the sale details.',ask:['What does the note say we paid?','Could the balance have moved for another reason (a sale, depreciation)?','So which number is the cash: the balance change or the purchase in the note?'],trap:'Using the balance change as the cash. Ask what else moves that balance.'},
 ppe_sale:{click:'Selling the old truck: the check you receive is Investing. Whatever "gain" or "loss" the books record is handled separately in Operating. The check is the only cash.',why:'Investing reports proceeds. Gains and losses are Net Income effects, not cash.',ask:['What did the buyer pay?','Is that the same as the gain? As the book value? Which one is money?'],trap:'Reporting book value or the gain as the proceeds.'},
 borrowing:{click:'A loan is like a friend lending you $50 for lunch. Your wallet is $50 fatter, but you did not earn it and you owe it back. It is not income; it is Financing.',why:'Operating shows what the business generates; borrowed cash is not generated, it is owed. Putting it in Operating would make a failing business look profitable.',ask:['Did we earn this money, or do we owe it back?','Who gave it to us: a customer or a lender?','So which door did it come through?'],trap:'"Cash came in, so it is revenue." Ask them whether their lunch loan was income.'},
 debt_repayment:{click:'Paying your friend back the $50. Your wallet is lighter, but you did not buy anything; nothing was consumed. Not an expense; Financing.',why:'Net Income already handled the cost of borrowing (interest). Returning principal is just giving a lender their money back.',ask:['Did we use anything up by repaying? (No.)','Who got the cash: a supplier or a lender?','So which door?'],trap:'Treating repayment as an expense. Interest is the expense; principal is not.'},
 stock_issuance:{click:'An investor hands Beacon $3,000 for a piece of the company. Beacon did not earn it by fixing bikes; it got it for selling ownership. Financing, not revenue.',why:'Revenue is from customers for work. Owner money is capital.',ask:['Did a customer pay this, or an owner?','Did Beacon do work to earn it?','So which door?'],trap:'"Money in = revenue." Ask who paid and why.'},
 dividends:{click:'Beacon hands owners $500 of profit as a thank-you. It is not a cost of fixing bikes; it is owners taking money out. Financing.',why:'Dividends never touch the Income Statement; they are a distribution to owners, so they cannot be an operating cost.',ask:['Who received this cash? (Owners.)','Did it help fix a single bike? (No.)','So which door?'],trap:'Treating dividends as an expense because cash left.'},
 noncash_investing_financing:{click:'Trading a baseball card for a bike. Nothing passed through your wallet, so your wallet cannot show it. Buying $8,000 of equipment by signing an $8,000 note is the same: a big deal, but zero cash moved. It gets a footnote, not a line.',why:'The statement explains the change in CASH. If a transaction moved no cash, it cannot be part of that explanation. Putting it in as +8,000 Financing and −8,000 Investing would be two made-up cash flows that happen to cancel.',ask:['How much cash moved in this deal? (Zero.)','Then can it be a cash inflow or outflow?','Where do we tell the reader about it instead? (A separate disclosure.)'],trap:'"Equipment went up, so Investing went down." Follow the cash; there was none.'}
};
function trickHTML(t){if(!t)return '';return `<p><b>Make it click:</b> ${esc(t.click)}</p><p><b>Why it has to work that way:</b> ${esc(t.why)}</p><p><b>Ask, in this order:</b></p><ol class="small">${t.ask.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p><b>Watch for:</b> ${esc(t.trap)}</p>`;}
function coachHTML(a,p){const t=TRICK[a.concept]||TRICK[p?.concept]||null;const steps=(p?.hints||[]).map(h=>`<li>${esc(h)}</li>`).join('');let plan='';try{plan=coachingHTML(a.concept,a,CFG);}catch(e){plan='';}return `<details class="coach" open><summary><b>Coach this</b> · make it make sense, then walk their numbers</summary>${trickHTML(t)}${plan?`<details class="plan"><summary><b>Teacher conversation plan</b> · probes, what to listen for, a 2-minute reteach, a fresh check with key</summary>${plan}</details>`:''}${p?.explanation?`<p><b>With their numbers:</b> ${esc(p.explanation)}</p>`:''}${steps?`<p><b>Walk it step by step (the same hints the app gives):</b></p><ol class="small">${steps}</ol>`:''}<p class="small muted"><b>Then check:</b> ask them to explain it back to you with the analogy in their own words, then one new problem in Practice → Focus on ${esc(conceptName(a.concept,CFG))} (opposite direction if it is a timing account). If they can only recite the rule, they do not have it yet.</p></details>`;}

function helpLine(h){if(!h||!h.n)return '—';const parts=[];parts.push(h.hintsOnStuck?`hints on ${h.hintsOnStuck} of ${h.n}`:`no hints on any of the ${h.n}`);if(h.backOnStuck)parts.push(`stepped back ${h.backOnStuck}×`);if(h.revealsOnStuck)parts.push(`worked answer ${h.revealsOnStuck}×`);let read='';if(!h.hintsOnStuck&&!h.revealsOnStuck)read=' → guessing without using the help; point them at the Hint button first.';else if(h.revealsOnStuck>=2)read=' → leaning on the worked answer; sit with them for one problem instead.';else if(h.hintsOnStuck&&h.hintsOnStuck>=h.n/2)read=' → using hints and still missing; the gap is conceptual, coach it.';return parts.join(', ')+`<span class="muted"> (overall: hints on ${h.hintsAll} of ${h.nAll}, worked answers ${h.revealsAll})</span>`+read;}

const PT_NAMES={operating:'Operating practice test',investing:'Investing practice test',investing2:'Investing practice test 2',financing:'Financing practice test',financing2:'Financing practice test 2',financing3:'Financing practice test 3'};const PT_STEPS=['See one built','Build, lines given','Build on a blank form','Why questions','Say it in words'];
function whereIs(r){const raw=String(r.currentModule||'');const [id,rest='']=raw.split('@');const [pos,st]=rest.split(':');if(id==='pt')return {label:PT_NAMES[pos]||'Practice test',detail:`step ${st} of 5 · ${PT_STEPS[Number(st)-1]||''}`};if(id==='round')return {label:'Extra round · '+(pos||''),detail:`level ${st||''}`};if(id==='testprep')return {label:'Practice Test page',detail:''};if(id==='practice')return {label:'Practice',detail:`question ${pos}${st?' · '+conceptName(st,CFG):''}`};if(pos==='build')return {label:'Building: '+id,detail:'capstone'};if(!rest&&id&&id!=='Learning map'){const m=MODS.find(x=>x.id===id);return m?{label:m.title,detail:''}:{label:id,detail:''};}const m=MODS.find(x=>x.id===id);if(!m)return {label:id||'Learning map',detail:''};return {label:m.title,detail:`screen ${pos}${st==='story'?' (story)':st?' · '+st:''}`};}

const STAGE_GROUPS=[['Statement',['Foundation']],['Operating',['Operating · Timing','Operating · Noncash','Operating ↔ Investing · Asset sales']],['Investing',['Investing · new method']],['Financing',['Financing · same method as Investing','Boundary']]];
function stageLine(r){const done=r.completedModules||[];return STAGE_GROUPS.map(([name,groups])=>{const mods=MODS.filter(m=>groups.includes(m.group));const d=mods.filter(m=>done.includes(m.id)).length;return `${name} ${d}/${mods.length}`;}).join(' · ');}
const PT_LABEL={operating:'Operating',investing:'Investing 1',investing2:'Investing 2',financing:'Financing 1',financing2:'Financing 2',financing3:'Financing 3'};
function ptLine(r){const st=r.testPrep?._status;if(!st)return '';const parts=[];for(const sec of ['operating','investing','investing2','financing','financing2','financing3']){const d=st.done?.[sec];const cur=st.current&&st.current.sec===sec&&!st.current.finished?st.current:null;if(cur)parts.push(`${PT_LABEL[sec]} PT: step ${cur.step}/5${cur.mc&&cur.step===4?` (${cur.mc.correct}/${cur.mc.i} so far)`:''}`);else if(d)parts.push(`${PT_LABEL[sec]} PT ✓ ${new Date(d).toLocaleDateString([],{month:'numeric',day:'numeric'})}`);}return parts.join(' · ');}
function idleMin(r){return Math.max(0,Math.round((Date.now()-(r.lastActive||0))/60000));}
function nowBoard(rs){if(!rs.length)return '<p class="muted">No students yet.</p>';const sorted=rs.slice().sort((a,b)=>idleMin(b)-idleMin(a));return `<div class="now-grid">${sorted.map(r=>{const w=whereIs(r),idle=idleMin(r),p=progressFor(r),acc=r.recentAccuracy;const cls=idle>=6?'idle':idle>=3?'slow':'';return `<button class="now-card ${cls} ${r.needsHelp?'flag':''}" data-student="${esc(r.uid)}"><div class="now-name">${esc(r.name)}${r.needsHelp?' <span class="flagdot" title="needs a check-in">●</span>':''}</div><div class="now-where">${esc(w.label)}</div><div class="now-detail small muted">${esc(w.detail)}</div><div class="now-meta small">${idle===0?'active now':idle+' min idle'} · ${p.modsDone}/${MODS.length} done · ${acc==null?'—':Math.round(acc*100)+'%'}</div>${redoPending(r).length?`<div class="small redo">Redo (rewritten): ${esc(redoPending(r).join(', '))}</div>`:''}<div class="small muted">${esc(stageLine(r))}</div>${ptLine(r)?`<div class="small">${esc(ptLine(r))}</div>`:''}</button>`;}).join('')}</div>`;}

function redoPending(r){const done=r.completedModules||[];const idx=id=>MODS.findIndex(m=>m.id===id);return Object.keys(REVISIT_REQUIRED).filter(id=>!done.includes(id)&&(done.some(c=>idx(c)>idx(id))||(r.recentAttempts||[]).some(a=>a.moduleId===id&&(a.contentVersion||'')<'2026.10.15'))).map(id=>MODS.find(m=>m.id===id)?.title||id);}

// ---------- Today vs before, and integrity signals (from cfl_attempts) ----------
let todayAttempts=null,todayLoading=false,todayError='';
function dayKey(ts){const d=new Date(ts);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function startOfToday(){const d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function baselineKey(){return 'cfl_teacher_baseline_'+dayKey(Date.now());}
function takeBaseline(force=false){try{const k=baselineKey();if(!force&&localStorage.getItem(k))return;const b={};for(const r of rows){b[r.uid||r.name]={modules:(r.completedModules||[]).length,secure:r.secure||0,attempts:r.attemptCount||0,at:Date.now()};}localStorage.setItem(k,JSON.stringify(b));}catch(e){}}
function baseline(){try{return JSON.parse(localStorage.getItem(baselineKey())||'{}');}catch(e){return {};}}
async function loadToday(){if(!connection||todayLoading)return;todayLoading=true;todayError='';render();try{const {fs,db}=connection;const snap=await fs.getDocs(fs.query(fs.collection(db,'cfl_attempts'),fs.where('timestamp','>=',startOfToday())));todayAttempts=snap.docs.map(d=>d.data());}catch(e){todayError=String(e?.message||e);}todayLoading=false;render();}
function activeMinutes(atts){const ts=atts.map(a=>a.timestamp).sort((a,b)=>a-b);let s=0;for(let i=1;i<ts.length;i++){const gap=ts[i]-ts[i-1];if(gap<5*60000)s+=gap;}return Math.round(s/60000);}
function todayRow(r){const atts=(todayAttempts||[]).filter(a=>a.uid===r.uid);const b=baseline()[r.uid||r.name];const modsNow=(r.completedModules||[]).length;const indep=atts.filter(a=>!a.revealed&&!(a.hintsUsed||[]).length&&a.promptType!=='observe');const correct=indep.filter(a=>a.correct).length;const mods=new Set(atts.map(a=>a.moduleId).filter(Boolean));return {atts,prompts:atts.length,indep:indep.length,acc:indep.length?correct/indep.length:null,mins:activeMinutes(atts),modsToday:b?modsNow-b.modules:null,secToday:b?(r.secure||0)-b.secure:null,modsNow,modulesTouched:mods.size,before:(r.attemptCount||0)-atts.length};}
function integrityRow(r){const atts=(todayAttempts||[]).filter(a=>a.uid===r.uid&&a.promptType&&a.promptType!=='observe');const timed=atts.filter(a=>typeof a.stepSec==='number');const secs=timed.map(a=>a.stepSec).sort((a,b)=>a-b);const median=secs.length?secs[Math.floor(secs.length/2)]:null;const fast=timed.filter(a=>a.correct&&a.stepSec<5&&a.promptType!=='choice').length;const fastChoice=timed.filter(a=>a.correct&&a.stepSec<3&&a.promptType==='choice').length;const away=atts.reduce((n,a)=>n+(a.away||0),0);const awaySec=atts.reduce((n,a)=>n+(a.awaySec||0),0);const awayCorrect=atts.filter(a=>(a.away||0)>0&&a.correct).length;const pasted=atts.reduce((n,a)=>n+(a.pasted||0),0);const flags=[];if(awayCorrect>=3)flags.push(`${awayCorrect} answers were correct right after leaving the tab`);if(pasted>=1)flags.push(`${pasted} paste${pasted>1?'s':''} into an answer box`);if(timed.length>=10&&(fast+fastChoice)/timed.length>0.4)flags.push(`${Math.round((fast+fastChoice)/timed.length*100)}% of correct answers came in under 5 seconds`);if(awaySec>=600)flags.push(`${Math.round(awaySec/60)} min away from the tab while a question was open`);return {n:atts.length,timed:timed.length,median,fast:fast+fastChoice,away,awaySec,awayCorrect,pasted,flags,score:flags.length};}
function todayHTML(rs){if(!connection)return '<p class="small muted">Live class record needed for this panel.</p>';const b=baseline();const hasB=Object.keys(b).length>0;const head=`<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center"><button id="load-today" ${todayLoading?'disabled':''}>${todayLoading?'Loading…':todayAttempts?'Refresh today\'s answers':'Load today\'s answers'}</button><button id="mark-start">${hasB?'Re-mark start of class':'Mark start of class (baseline)'}</button><span class="small muted">${hasB?`Baseline taken ${new Date(Object.values(b)[0]?.at||Date.now()).toLocaleTimeString()}: modules/secure deltas are since then.`:'Press at the start of class so module and Secure counts can be compared to now.'}${todayError?` <b style="color:#b34d45">${esc(todayError)}</b>`:''}</span></div>`;if(!todayAttempts)return head+'<p class="small muted">Load today\'s answers to see per-student progress since midnight (prompts, independent accuracy, active minutes) and the integrity signals below.</p>';const data=rs.map(r=>({r,t:todayRow(r)})).sort((a,b)=>b.t.prompts-a.t.prompts);const tot=data.reduce((n,x)=>n+x.t.prompts,0);const totMods=data.reduce((n,x)=>n+(x.t.modsToday||0),0);return head+`<p class="small">Class today: <b>${tot}</b> answers · <b>${data.filter(x=>x.t.prompts>0).length}</b> students active${hasB?` · <b>${totMods}</b> modules completed since the baseline`:''}.</p><table class="t small"><thead><tr><th>Student</th><th>Answers today</th><th>Answers before today</th><th>Indep. accuracy today</th><th>Active min</th><th>Modules done today</th><th>Modules done total</th><th>Secure gained today</th><th>Now</th></tr></thead><tbody>${data.map(({r,t})=>`<tr class="${t.prompts===0?'muted':''}"><td><button class="link" data-detail="${esc(r.uid||r.name)}">${esc(r.name)}</button></td><td><b>${t.prompts}</b></td><td>${t.before}</td><td>${t.acc==null?'—':Math.round(t.acc*100)+'%'}</td><td>${t.mins}</td><td>${t.modsToday==null?'—':(t.modsToday>0?'+':'')+t.modsToday}</td><td>${t.modsNow}/${MODS.length}</td><td>${t.secToday==null?'—':(t.secToday>0?'+':'')+t.secToday}</td><td class="small">${esc(whereIs(r))}</td></tr>`).join('')}</tbody></table>`;}
function integrityHTML(rs){if(!todayAttempts)return '<p class="small muted">Load today\'s answers (panel above) first.</p>';const data=rs.map(r=>({r,i:integrityRow(r)})).filter(x=>x.i.n>0).sort((a,b)=>b.i.score-a.i.score||b.i.awayCorrect-a.i.awayCorrect);const flagged=data.filter(x=>x.i.flags.length);return `<p class="small muted">These are signals, not proof. A student can switch tabs to check notes, answer fast on an easy step, or paste a number they typed elsewhere. Use them to decide who to watch or talk to, and compare with the answer log (open the student, then "Load answer history").</p>${flagged.length?`<div class="help-cards">${flagged.map(({r,i})=>`<div class="help-card warn"><b>${esc(r.name)}</b><ul class="small">${i.flags.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><div class="small muted">median ${i.median==null?'—':i.median+'s'} per step · ${i.away} tab switches (${Math.round(i.awaySec/60)} min away) · ${i.pasted} pastes · ${i.fast} fast correct of ${i.timed}</div></div>`).join('')}</div>`:'<p class="small">No one is flagged today.</p>'}<details><summary class="small">All students (timing and tab data)</summary><table class="t small"><thead><tr><th>Student</th><th>Answers</th><th>Median sec/step</th><th>Fast correct (&lt;5s)</th><th>Tab switches</th><th>Min away</th><th>Correct right after leaving</th><th>Pastes</th></tr></thead><tbody>${data.map(({r,i})=>`<tr><td>${esc(r.name)}</td><td>${i.n}</td><td>${i.median==null?'—':i.median}</td><td>${i.fast}/${i.timed}</td><td>${i.away}</td><td>${Math.round(i.awaySec/60)}</td><td>${i.awayCorrect}</td><td>${i.pasted}</td></tr>`).join('')}</tbody></table></details><p class="small muted">Timing and tab data exist only for answers given after this update went live (v1.3.3); earlier answers show in counts but not in the timing columns.</p>`;}

function prepHTML(rs){const secs=['operating','investing','financing'];const have=rs.filter(r=>r.testPrep&&Object.values(r.testPrep).some(v=>v&&v.length));if(!have.length)return '<p class="small muted">No Test Prep rounds in the class record yet. (If students have done rounds and nothing shows, the Firestore rules need the one-line update in firestore.rules: add \'testPrep\' to the cfl_stats key list.)</p>';const missed={};for(const r of have)for(const sec of secs)for(const h of (r.testPrep[sec]||[]))for(const w of (h.wrong||[]))missed[sec+'|'+w]=(missed[sec+'|'+w]||0)+1;const top=Object.entries(missed).sort((a,b)=>b[1]-a[1]).slice(0,8);const cell=(r,sec)=>{const h=r.testPrep?.[sec]||[];if(!h.length)return '<td class="muted">—</td>';const best=h.reduce((b,x)=>x.score/x.max>b.score/b.max?x:b,h[0]);const last=h.at(-1);const pct=Math.round(last.score/last.max*100);return `<td class="${pct>=85?'good':pct>=60?'mid':'low'}"><b>${last.score}/${last.max}</b> L${last.level}<br><small class="muted">best ${Math.round(best.score/best.max*100)}% · ${h.length} round${h.length>1?'s':''} · ${new Date(last.ts).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small>${(last.wrong||[]).length?`<br><small class="redo">missed: ${esc(last.wrong.slice(0,4).join(', '))}${last.wrong.length>4?'…':''}</small>`:''}</td>`;};return `${top.length?`<p class="small"><b>Most-missed lines in the class:</b> ${top.map(([k,n])=>{const [sec,w]=k.split('|');return `${esc(w)} <span class="muted">(${sec}, ${n})</span>`;}).join(' · ')}</p>`:''}<table class="t small"><thead><tr><th>Student</th><th>Practice tests</th><th>Operating “why” (12 MC)</th><th>Operating builds (last · best)</th><th>Investing 1 “why” (12 MC)</th><th>Investing 2 “why” (12 MC)</th><th>Investing builds</th><th>Financing 1 “why” (12 MC)</th><th>Financing 2 “why” (12 MC)</th><th>Financing 3 “why” (12 MC)</th><th>Financing builds</th></tr></thead><tbody>${rs.map(r=>{const why=k=>{const wu=r.testPrep?.[k]||[];const lw=wu.at(-1);return `<td class="${lw?(lw.score/lw.max>=0.85?'good':lw.score/lw.max>=0.6?'mid':'low'):'muted'}">${lw?`<b>${lw.score}/${lw.max}</b><br><small class="muted">${new Date(lw.ts).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small>`:'—'}</td>`;};return `<tr><td><button class="link" data-detail="${esc(r.uid||r.name)}">${esc(r.name)}</button></td><td class="small">${esc(ptLine(r)||'—')}</td>${why('warmup')}${cell(r,'operating')}${why('why_investing')}${why('why_investing2')}${cell(r,'investing')}${why('why_financing')}${why('why_financing2')}${why('why_financing3')}${cell(r,'financing')}</tr>`;}).join('')}</tbody></table><p class="small muted">Green 85%+, amber 60–84%, red below 60% on the latest round. "Missed" lists the lines wrong on that round, so you can tell a student which account to review.</p>`;}
function helpCards(rs){const SK=(k)=>SKILL_NAMES?.[k]||k;const cards=[];for(const r of rs){const at=(r.recentAttempts||[]).slice(-25);if(at.length<4)continue;const wrong=at.filter(a=>!a.correct);const acc=at.length?1-wrong.length/at.length:1;const conceptual=wrong.filter(a=>a.misconceptionCode&&!['M27','M31','M33'].includes(a.misconceptionCode));const counts={};for(const a of conceptual)counts[a.misconceptionCode]=(counts[a.misconceptionCode]||0)+1;const topCode=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];const bySkill={};for(const a of at){const k=a.concept+'|'+a.skill;(bySkill[k]||=(bySkill[k]={n:0,w:0}));bySkill[k].n++;if(!a.correct)bySkill[k].w++;}const stuck=Object.entries(bySkill).filter(([k,v])=>v.n>=2).sort((a,b)=>(b[1].w/b[1].n)-(a[1].w/a[1].n))[0];const sectionOnly=wrong.length&&wrong.every(a=>a.misconceptionCode==='M27');const stuckKey=stuck?stuck[0]:null;const stuckAt=stuckKey?at.filter(a=>a.concept+'|'+a.skill===stuckKey):[];const hintsOnStuck=stuckAt.filter(a=>(a.hintsUsed||[]).length).length,revealsOnStuck=stuckAt.filter(a=>a.revealed).length,backOnStuck=stuckAt.filter(a=>(a.hintsUsed||[]).includes('Backward reasoning support')).length;const hintsAll=at.filter(a=>(a.hintsUsed||[]).length).length,revealsAll=at.filter(a=>a.revealed).length;const helpUse={hintsOnStuck,revealsOnStuck,backOnStuck,n:stuckAt.length,hintsAll,revealsAll,nAll:at.length};const urgent=acc<0.6||(topCode&&topCode[1]>=3)||(r.reveals||0)>=2;if(!urgent)continue;const last=conceptual.at(-1)||wrong.at(-1);cards.push({r,acc,topCode,stuck,sectionOnly,last,helpUse});}
 cards.sort((a,b)=>a.acc-b.acc);if(!cards.length)return '<p class="muted">Nobody is flagged right now. Everyone recently flagged is above 60% with no repeated pattern.</p>';
 return cards.slice(0,10).map(c=>{const [concept,skill]=c.stuck?c.stuck[0].split('|'):[null,null];const code=c.topCode?.[0];return `<details class="help-card"><summary class="help-head"><span><b>${esc(c.r.name)}</b> <span class="muted small">${Math.round(c.acc*100)}%</span> · ${c.stuck?esc(conceptName(concept,CFG))+' → '+esc(SK(skill)):'mixed misses'}${code?` · <span class="muted">${esc(plainTitle(code))}</span>`:''}</span><span class="small muted">${esc(whereIs(c.r).label)} · tap to coach</span></summary><div class="help-body"><button class="link small" data-student="${esc(c.r.uid)}">full detail</button>${c.stuck?`<div><b>Stuck on:</b> ${esc(conceptName(concept,CFG))} → ${esc(SK(skill))} (${c.stuck[1].w} of ${c.stuck[1].n} wrong)</div><div><b>Using help there?</b> ${helpLine(c.helpUse)}</div>`:''}${code?`<div><b>Keeps doing:</b> ${esc(plainTitle(code))} (${c.topCode[1]}×). ${esc(plainWhat(code))}</div><div><b>Say:</b> ${esc(TEACH_PROMPTS[code]||'')}</div>`:c.sectionOnly?'<div><b>Keeps doing:</b> choosing the wrong statement section only. Likely not reading the section menu; remind them timing adjustments live in Operating, then watch one answer.</div>':'<div><b>Keeps doing:</b> no single pattern; mixed misses. Sit for one problem and listen to the reasoning.</div>'}${c.last?`<div class="small muted">Last wrong: ${esc(conceptName(c.last.concept,CFG))} · ${esc(SK(c.last.skill))} · answered “${esc(readable(c.last.response))}”, correct was “${esc(readable(c.last.correctResponse))}” <button class="link small" data-open-attempt="${esc(c.r.uid)}|${c.last.attemptId}">open this problem</button></div>${(()=>{let p=null;try{p=generate(c.last.concept,c.last.seed,c.last.scaffoldLevel??2,c.last.direction,CFG);}catch(e){}return coachHTML(c.last,p);})()}`:''}</div></details>`;}).join('');}
function render(){const rs=filtered();const misconceptions={};for(const r of rs)for(const [code,count] of Object.entries(r.misconceptionCounts||{})){if(count)(misconceptions[code]||= []).push(r);}const liveReady=!!(window.__cflLive)||rows.some(r=>r.importedFrom||r.local);const sec=(title,body,open,hint='')=>`<details class="panel" ${open?'open':''}><summary><span>${title}</span>${hint?`<span class="small muted">${hint}</span>`:''}</summary><div class="panel-body">${body}</div></details>`;root.innerHTML=`<div class="command"><div class="cmd-tiles"><div class="tile"><strong>${rs.length}</strong><span>students</span></div><div class="tile ${rs.filter(r=>idleMin(r)>=6).length?'warn':''}"><strong>${rs.filter(r=>idleMin(r)>=6).length}</strong><span>idle 6+ min</span></div><div class="tile ${rs.filter(r=>r.needsHelp).length?'warn':''}"><strong>${rs.filter(r=>r.needsHelp).length}</strong><span>need a check-in</span></div><div class="tile"><strong>${rs.filter(r=>Object.values(r.capstones||{}).some(c=>c.completed)).length}</strong><span>finished a statement</span></div></div><div class="jump">Jump to: ${['now:Right now','today:Today vs before','prep:Test Prep','integ:Integrity','help:Who to help','overview:Overview','concepts:Concept map','skills:Skill map','misc:Misconceptions','caps:Capstones','curr:Curriculum'].map(x=>{const [id,l]=x.split(':');return `<a href="#sec-${id}">${l}</a>`;}).join(' · ')}</div></div><div id="sec-now"></div>${sec('Right now: who is on what',nowBoard(rs),true,'sorted by idle time · tap a card for detail')}<section class="panel" open style="padding:10px 14px;margin-bottom:12px"><b>Open what students see</b> <span class="small muted">(preview mode: nothing you do is saved to the class record)</span><div class="row" style="flex-wrap:wrap;gap:8px;margin-top:6px"><a class="button" target="_blank" href="./index.html?preview=1&route=home">Learning map</a><a class="button" target="_blank" href="./index.html?preview=1&route=testprep">Practice Test page</a><a class="button" target="_blank" href="./index.html?preview=1&pt=investing">Investing practice test</a><a class="button" target="_blank" href="./index.html?preview=1&pt=financing">Financing practice test</a><a class="button" target="_blank" href="./index.html?preview=1&pt=operating">Operating practice test</a><a class="button" target="_blank" href="./index.html?preview=1&route=practice">Practice page</a><a class="button" target="_blank" href="./index.html?preview=1&route=build">Build a Statement</a><a class="button" target="_blank" href="./index.html">Student app (your own login, saved)</a></div></section><div id="sec-today"></div>${sec('Today vs before',todayHTML(rs),true,'answers, accuracy and minutes since midnight · modules since your baseline')}<div id="sec-prep"></div>${sec('Test Prep results',prepHTML(rs),true,'latest and best round per section · most-missed lines')}<div id="sec-integ"></div>${sec('Integrity signals',integrityHTML(rs),false,'tab switching, time per step, pastes · signals, not proof')}<div id="sec-help"></div><details class="panel" open><summary><span>Who to help now</span><span class="small muted">students under 60%, repeating a pattern, or using worked answers</span></summary><div class="panel-body"><section class="heat-section help-section"><p class="small muted">Students under 60% on recent answers, with a repeated pattern, or who used the worked answer twice. Section-menu misclicks are set aside so the real reasoning gap shows.</p>${helpCards(rs)}</section></div></details><div id="sec-curr"></div>${sec('Browse the curriculum',curriculumHTML().replace(/^<section class="heat-section"><h2>Browse the curriculum<\/h2>|<\/section>$/g,''),false,'every screen, question and answer key')}${!liveReady&&!rs.length?'<p class="notice">No records loaded yet. Numbers below are not class counts until the live connection is authorized (see the status line above) or backups are imported.</p>':''}<div id="sec-overview"></div><details class="panel"><summary><span>Overview table</span><span class="small muted">done · pace · ETA · accuracy · hints</span></summary><div class="panel-body"><div class="overview"><div class="card"><strong>${rs.length}</strong><p>learners in view</p></div><div class="card"><strong>${rs.filter(r=>r.needsHelp).length}</strong><p>may need a conversation</p></div><div class="card"><strong>${rs.filter(r=>r.secure>=8).length}</strong><p>8+ concepts secure</p></div><div class="card"><strong>${rs.filter(r=>Object.values(r.capstones||{}).some(c=>c.completed)).length}</strong><p>completed a statement</p></div></div>${!rs.length?'<div class="notice">No student records yet. In local mode, import students’ exported progress JSON files. With Firebase configured, authorized teachers receive a live roster.</div>':''}<div class="scroll-table"><table class="dashboard-table"><caption>Live class overview</caption><thead><tr>${['Student','Current module','Done','Pace','ETA to finish Learn²','Secure / mastered','Recent independent accuracy','Hints / reveals¹','Capstone','Last active','Support'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>{const p=progressFor(r);return `<tr><td><button data-student="${esc(r.uid)}">${esc(r.name)}</button></td><td>${esc(whereIs(r).label)}<br><span class="small muted">${esc(whereIs(r).detail)}</span></td><td>${p.modsDone}/${MODS.length} modules<br><span class="small muted">${p.promptsDone}/${TOTAL_PROMPTS} q</span>${redoPending(r).length?`<br><span class="small redo">redo: ${esc(redoPending(r).join(', '))}</span>`:''}</td><td>${p.pace?Math.round(p.pace*60)+' q/h':'—'}</td><td>${etaText(p)}</td><td>${r.secure} / ${r.mastered}</td><td>${pct(r.recentAccuracy)}</td><td>${r.hints} / ${r.reveals}</td><td>${Object.values(r.capstones||{}).filter(c=>c.completed).length} complete</td><td>${new Date(r.lastActive).toLocaleString()}</td><td class="${r.needsHelp?'needs-help':''}">${r.needsHelp?'Needs a check-in':'—'}</td></tr>`;}).join('')}</tbody></table></div><p class="small">² Remaining questions at this student's recent pace, weighted up for the harder later modules (noncash, gains, investing, financing). Add about 20 minutes for the guided statement. ¹ Recent 20 responses. Hints are learning support, not penalties. “Secure” includes mastered concepts. Readiness indicators are suggestions, not grades.</p></div></details><div id="sec-concepts"></div><details class="panel"><summary><span>Concept heat map</span><span class="small muted">status and score per concept</span></summary><div class="panel-body"><section class="heat-section"><h2>Concept heat map</h2><p class="small"><b>What the labels mean:</b> <b>Learning</b> = lesson seen, only guided answers so far (not scored). <b>Practicing</b> = answering on their own but not yet consistent. <b>Secure</b> = about 75%+ on recent independent problems, both directions seen. <b>Mastered</b> = 85%+ including mixed practice, no worked answers lately. The number under each label is the score on independent problems (hints lower it; worked answers count as zero).</p><div class="scroll-table"><table class="dashboard-table"><thead><tr><th>Student</th>${COLUMNS.map(c=>`<th>${esc(conceptName(c,CFG))}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.name)}</td>${COLUMNS.map(c=>`<td>${heat(r.concepts?.[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div></details><div id="sec-skills"></div><details class="panel"><summary><span>Which link needs work?</span><span class="small muted">pick a concept, see each skill</span></summary><div class="panel-body"><section class="heat-section"><h2>Which link needs work?</h2><label>Concept<select id="concept-filter">${Object.keys(CONCEPT_NAMES).map(c=>`<option value="${c}" ${c===selectedConcept?'selected':''}>${esc(conceptName(c,CFG))}</option>`).join('')}</select></label><div class="scroll-table"><table class="dashboard-table"><thead><tr><th>Student</th>${['locate','compute_change','interpret','recognition_cash_connect','adjustment_direction','place_line'].map(k=>`<th>${SKILL_NAMES[k]}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.name)}</td>${['locate','compute_change','interpret','recognition_cash_connect','adjustment_direction','place_line'].map(k=>`<td>${heat(r.skills?.[selectedConcept]?.[k])}<br><small>${r.skills?.[selectedConcept]?.[k]?.count||0} recent responses</small></td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div></details><div id="sec-misc"></div><details class="panel"><summary><span>Misconceptions to discuss</span><span class="small muted">class-wide patterns with what to say</span></summary><div class="panel-body"><section class="heat-section"><h2>Misconceptions to discuss</h2><div class="misconceptions">${Object.entries(misconceptions).sort((a,b)=>b[1].length-a[1].length).map(([code,students])=>{const total=students.reduce((n,r)=>n+(r.misconceptionCounts[code]||0),0);const top=students.slice().sort((a,b)=>(b.misconceptionCounts[code]||0)-(a.misconceptionCounts[code]||0)).slice(0,3).map(r=>`${esc(r.name)} (${r.misconceptionCounts[code]})`).join(', ');return `<div class="misc-row"><button data-misconception="${code}"><b>${students.length} student${students.length===1?'':'s'}</b> · ${esc(plainTitle(code))} <span class="muted">· ${total} times</span></button><p class="small"><b>What they're doing:</b> ${esc(plainWhat(code))}</p>${TEACH_PROMPTS[code]?`<p class="small"><b>Say:</b> ${esc(TEACH_PROMPTS[code])}</p>`:''}<p class="small muted">Most often: ${top}</p></div>`;}).join('')||'<p class="muted">No misconception patterns recorded yet.</p>'}</div></section></div></details><div id="sec-caps"></div><details class="panel"><summary><span>Capstone evidence</span><span class="small muted">statement builds and tie-outs</span></summary><div class="panel-body"><section class="heat-section"><h2>Capstone evidence</h2><div class="scroll-table"><table class="dashboard-table"><thead><tr><th>Student</th><th>Case</th><th>Status</th><th>Operating</th><th>Investing</th><th>Financing</th><th>Tie-out</th><th>Initially incorrect</th><th>Hints / reveals</th></tr></thead><tbody>${rs.flatMap(r=>Object.values(r.capstones||{}).map(c=>`<tr><td><button data-student="${esc(r.uid)}">${esc(r.name)}</button></td><td>${esc(c.id)}</td><td>${c.completed?'Completed':'Started'}</td>${['operating','investing','financing'].map(s=>`<td>${c.result?money(c.result.actual[s]):'—'}</td>`).join('')}<td>${c.result?.ties?'✓ Yes':'Not yet'}</td><td>${esc(c.initialWrong?.join(', ')||'—')}</td><td>${Object.values(c.hints||{}).flat().length} / ${Object.values(c.hints||{}).flat().filter(h=>h.startsWith('REVEAL')).length}</td></tr>`)).join('')}</tbody></table></div></section></div></details>`;
 document.querySelector('#concept-filter').onchange=e=>{selectedConcept=e.target.value;render();};root.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>detail(rows.find(r=>r.uid===b.dataset.student)));root.querySelectorAll('[data-module-key]').forEach(b=>b.onclick=()=>openModuleKey(b.dataset.moduleKey));root.querySelectorAll('[data-open-attempt]').forEach(b=>b.onclick=()=>{const [uid,id]=b.dataset.openAttempt.split('|');const r=rows.find(x=>x.uid===uid);const a=(r?.recentAttempts||[]).find(x=>x.attemptId===id);if(a)openAttempt(a);});root.querySelectorAll('[data-misconception]').forEach(b=>b.onclick=()=>{const code=b.dataset.misconception;document.querySelector('#detail-title').textContent=plainTitle(code);const ex=r=>{const a=(r.recentAttempts||[]).filter(x=>x.misconceptionCode===code).slice(-2);return a.length?`<div class="small muted">Recent: ${a.map(x=>`${esc(conceptName(x.concept,CFG))} · answered “${esc(readable(x.response))}”, correct was “${esc(readable(x.correctResponse))}”`).join(' · ')}</div>`:'';};document.querySelector('#detail-body').innerHTML=`<p>${esc(plainWhat(code))}</p><p><b>Say:</b> ${esc(TEACH_PROMPTS[code]||'')}</p><ul>${misconceptions[code].slice().sort((a,b)=>(b.misconceptionCounts[code]||0)-(a.misconceptionCounts[code]||0)).map(r=>`<li><b>${esc(r.name)}</b> · ${r.misconceptionCounts[code]} time${r.misconceptionCounts[code]===1?'':'s'}${ex(r)}</li>`).join('')}</ul>`;dialog.showModal();});wireToday();}
function readable(value){if(value==null)return '—';if(Array.isArray(value))return value.map(readable).join('; ');if(typeof value==='object')return Object.entries(value).map(([k,v])=>`${k}: ${typeof v==='object'?'statement entries':readable(v)}`).join(' · ');return String(value);}
function attemptsHTML(attempts){return [...attempts].reverse().map(a=>`<article class="detail-attempt"><b>${a.correct?'✓':'△'} ${esc(conceptName(a.concept,CFG))} · ${esc(SKILL_NAMES[a.skill]||a.skill)}</b><p>${esc(a.problemId)} · seed ${a.seed} · ${new Date(a.timestamp).toLocaleString()}</p><p><b>Response:</b> ${esc(readable(a.response))}</p><p><b>Expected:</b> ${esc(readable(a.correctResponse))}</p><p><b>Support:</b> ${a.hintsUsed?.length||0} hints · ${a.revealed?'revealed':'not revealed'} · ${a.elapsedMs!=null?Math.round(a.elapsedMs/1000)+' seconds':'time not recorded'}</p>${a.misconceptionCode?`<p>${a.misconceptionCode} — ${esc(MISCONCEPTIONS[a.misconceptionCode]||'')}</p>`:''}</article>`).join('')||'<p>No attempts yet.</p>';}
function detail(r){if(!r)return;document.querySelector('#detail-title').textContent=r.name+' · Learning evidence';document.querySelector('#detail-body').innerHTML=`<h3>Learning path</h3><p>${esc((r.completedModules||[]).map(c=>conceptName(c,CFG)).join(' → ')||'Not yet completed a module')}</p><div class="skill-list">${Object.entries(r.concepts||{}).filter(([,m])=>m.state!=='Not started').map(([c,m])=>`<span>${esc(conceptName(c,CFG))}: ${m.state}</span>`).join('')}</div><h3>Written explanations</h3>${(r.explanations||[]).map(e=>`<p><b>${esc(conceptName(e.moduleId,CFG))}</b><br>${esc(e.text)}</p>`).join('')||'<p>No milestone writing yet.</p>'}${Object.values(r.capstones||{}).filter(c=>c.explanation).map(c=>`<p><b>${esc(c.id)}</b><br>${esc(c.explanation)}</p>`).join('')}<h3>Capstone lines</h3>${Object.values(r.capstones||{}).map(c=>`<details><summary>${esc(c.id)}</summary>${(c.entries||[]).map(l=>`<p>${esc(l.label)} · ${esc(l.section)} · ${money(l.amount)} ${c.initialWrong?.includes(l.id)?'· initially incorrect':''}</p>`).join('')}</details>`).join('')}<h3>Recent responses</h3>${connection?'<button id="load-attempts">Load full attempt history</button>':''}<div id="attempt-detail">${attemptsHTML(r.recentAttempts||[])}</div>`;try{document.querySelector('#detail-body').insertAdjacentHTML('beforeend',`<details class="plan" open><summary><b>Individual follow-up</b></summary>${studentGuidanceHTML(r,CFG)}</details>`);}catch(e){}dialog.showModal();document.querySelector('#load-attempts')?.addEventListener('click',async e=>{e.target.disabled=true;try{const {fs,db}=connection;const snap=await fs.getDocs(fs.query(fs.collection(db,'cfl_attempts'),fs.where('uid','==',r.uid)));const a=snap.docs.map(d=>d.data()).sort((a,b)=>a.timestamp-b.timestamp);document.querySelector('#attempt-detail').innerHTML=attemptsHTML(a);}catch{document.querySelector('#attempt-detail').textContent='Could not load history. Check connection and teacher authorization.';}e.target.disabled=false;});}
function blocks(){const el=document.querySelector('#block'),value=el.value;el.innerHTML='<option value="">All classes</option>'+[...new Set([...(CFG.blocks||[]).map(b=>b.id),...rows.map(r=>r.block)])].map(id=>`<option value="${esc(id)}">${esc((CFG.blocks||[]).find(b=>b.id===id)?.name||id)}</option>`).join('');el.value=value;}
document.querySelector('#block').onchange=render;document.querySelector('#sort').onchange=render;document.querySelector('#close-detail').onclick=()=>dialog.close();
document.querySelector('#export-csv').onclick=()=>{const where=r=>{const w=whereIs(r);return (w.label||'')+(w.detail?' · '+w.detail:'');};const ptCells=r=>{const st=r.testPrep?._status||{};return ['operating','investing','investing2','financing','financing2','financing3'].map(sec=>{const d=st.done?.[sec];const cur=st.current&&st.current.sec===sec&&!st.current.finished?st.current:null;return cur?`in progress · step ${cur.step}/5`:d?`done ${new Date(d).toLocaleDateString()}`:'';});};const tilesDone=r=>{const done=r.completedModules||[];return MODS.filter(m=>done.includes(m.id)).map(m=>String(MODS.indexOf(m)+1).padStart(2,'0')).join(' ');};const header=['Name','Block','Where they are','Stage progress','Tiles done (numbers)','Operating PT','Investing PT 1','Investing PT 2','Financing PT 1','Financing PT 2','Financing PT 3','Note','Current module (raw)','Introduced','Secure','Mastered','Recent independent accuracy','Recent hints','Recent reveals','Completed capstones','Misconceptions','Last active',...COLUMNS.map(c=>CONCEPT_NAMES[c]),...Object.keys(SKILL_NAMES).map(k=>selectedConcept+': '+k)];const rows0=filtered().filter(r=>!/^test\b/i.test(String(r.name||'')));const counts={};rows0.forEach(r=>{const k=String(r.name||'').trim().toLowerCase();counts[k]=(counts[k]||0)+1;});const data=rows0.map(r=>[r.name,r.block,where(r),stageLine(r),tilesDone(r),...ptCells(r),counts[String(r.name||'').trim().toLowerCase()]>1?'duplicate name — same student on more than one device; use the row with the later Last active':'',r.currentModule,r.introduced,r.secure,r.mastered,pct(r.recentAccuracy),r.hints,r.reveals,Object.values(r.capstones||{}).filter(c=>c.completed).map(c=>c.id).join('; '),Object.entries(r.misconceptionCounts||{}).map(([k,n])=>k+': '+n).join('; '),new Date(r.lastActive).toISOString(),...COLUMNS.map(c=>r.concepts?.[c]?.state||'Not started'),...Object.keys(SKILL_NAMES).map(k=>r.skills?.[selectedConcept]?.[k]?.state||'Not started')]);download('cash-flow-lab-class.csv',csv([header,...data]),'text/csv;charset=utf-8');};
document.querySelector('#import-students').onchange=async e=>{const errors=[];for(const file of e.target.files){try{if(file.size>20000000)throw new Error('File too large');const s=migrate(JSON.parse(await file.text()));if(!s.identity)throw new Error('Missing student');const summary=summarize(s,CFG);rows=rows.filter(r=>r.uid!==summary.uid);rows.push(summary);}catch{errors.push(file.name);}}status.textContent=errors.length?'Some files could not be read: '+errors.join(', '):'Imported records for this session. Export a class CSV to retain this view.';blocks();render();};
blocks();render();
(async()=>{if(!CFG.firebase){status.textContent='Local mode · current device + imported student backups. Firebase is not configured.';return;}try{connection=await teacherConnection(CFG);if(!connection.authorized){status.textContent=`Teacher setup: authorize this browser UID in cfl_teachers: ${connection.uid}. Create that document in Firebase Console, then reload. No class data has been queried.`;connection=null;return;}status.textContent='Authorized teacher · live class records';const {fs,db}=connection;fs.onSnapshot(fs.collection(db,'cfl_stats'),snap=>{window.__cflLive=true;rows=snap.docs.map(d=>d.data());takeBaseline(false);status.textContent=`Authorized · live class records · ${rows.length} student${rows.length===1?'':'s'} · updated ${new Date().toLocaleTimeString()}`;blocks();render();},()=>{status.textContent='Class data unavailable. Check Firestore rules and network; local import still works.';});}catch{status.textContent='Class connection unavailable. Local import and CSV export remain available.';}})();

function wireToday(){document.querySelector('#load-today')?.addEventListener('click',loadToday);document.querySelector('#mark-start')?.addEventListener('click',()=>{takeBaseline(true);render();});}
